<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">├──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpt-xxx.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # GPT 账号池</span></span>
